def card(title, text, cls=''):
    return f'<div class="card {cls}"><h3>{title}</h3><p>{text}</p></div>'
def note(text, kind='orange'):
    return f'<div class="note {kind}">{text}</div>'
def step(n, title, text):
    return f'<div class="step"><b class="number">{n}</b><div><h3>{title}</h3><p>{text}</p></div></div>'
def screen(name, caption, cls=''):
    return f'<figure class="screen {cls}"><a href="assets/{name}.png" target="_blank" rel="noopener" title="Mở ảnh thao tác kích thước đầy đủ"><img src="assets/{name}.png" alt="{escape(caption)}"></a><figcaption>{caption} · Ảnh giao diện với dữ liệu minh họa</figcaption></figure>'
def pill(text, kind=''):
    return f'<span class="pill {kind}">{text}</span>'
slides = []
def add(title, kicker, sub, body, cls=''):
    slides.append(dict(title=title,kicker=kicker,sub=sub,body=body,cls=cls))

