parts=[]
for i,s in enumerate(slides,1):
    header=f'<header class="slide-head"><span class="kicker">{s["kicker"]}</span><{"h1" if i==1 else "h2"}>{s["title"]}</{"h1" if i==1 else "h2"}><p class="sub">{s["sub"]}</p></header>'
    footer=f'<footer class="foot"><span><img src="assets/comsflow-logo.png" alt="ComsFlow">HƯỚNG DẪN HÀNG HOÀN V2</span><span>Dữ liệu minh họa • 09/11/2026</span><b>{i:02d} / {len(slides):02d}</b></footer>'
    parts.append(f'<section class="slide {s["cls"]} {"active" if i==1 else ""}" id="slide-{i}" data-title="{escape(s["title"].replace("<br>"," "))}" aria-label="Trang {i}: {escape(s["title"].replace("<br>"," "))}">{header}<div class="body">{s["body"]}</div>{footer}</section>')
script=r'''
const all=[...document.querySelectorAll('.slide')], chooser=document.querySelector('#chooser');let current=0;
all.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=String(i+1).padStart(2,'0')+' · '+s.dataset.title;chooser.append(o)});
function fit(){const bar=document.querySelector('.toolbar').offsetHeight+54;document.querySelector('.stage').style.height=document.body.dataset.mode==='slides'?Math.max(180,innerHeight-bar)+'px':'';document.documentElement.style.setProperty('--scale',Math.max(.1,Math.min((innerWidth-32)/1600,(innerHeight-bar-24)/900)))}
function select(i){current=Math.max(0,Math.min(all.length-1,i));all.forEach((s,n)=>s.classList.toggle('active',n===current));chooser.value=current;document.querySelector('#counter').textContent=(current+1)+' / '+all.length;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===all.length-1;if(document.body.dataset.mode==='read')all[current].scrollIntoView({behavior:'smooth',block:'start'});history.replaceState(null,'','#slide-'+(current+1))}
function mode(value){document.body.dataset.mode=value;document.querySelector('#reading').setAttribute('aria-pressed',value==='read');document.querySelector('#presenting').setAttribute('aria-pressed',value==='slides');fit()}
window.addEventListener('resize',fit);document.querySelector('#prev').onclick=()=>select(current-1);document.querySelector('#next').onclick=()=>select(current+1);chooser.onchange=()=>select(Number(chooser.value));document.querySelector('#reading').onclick=()=>mode('read');document.querySelector('#presenting').onclick=()=>mode('slides');
window.addEventListener('keydown',e=>{if(document.body.dataset.mode!=='slides'||/SELECT|INPUT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();select(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();select(current-1)}if(e.key==='Home')select(0);if(e.key==='End')select(all.length-1)});
mode(innerWidth<760||new URLSearchParams(location.search).get('mode')==='read'?'read':'slides');select(Math.max(0,Number(location.hash.replace('#slide-',''))-1)||0);document.fonts.ready.then(fit);
'''
html='<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ComsFlow • Hướng dẫn hàng hoàn V2</title><meta name="description" content="14 slide thao tác từ hai file nguồn đến nhận kiện, kiểm SKU và đối soát hãng vận chuyển."><style>'+css+'</style></head><body data-mode="slides"><nav class="toolbar" aria-label="Điều khiển tài liệu"><img src="assets/comsflow-logo.png" alt="ComsFlow"><div class="tools"><select id="chooser" aria-label="Chọn trang hướng dẫn"></select><button id="presenting" aria-pressed="true">Trình chiếu</button><button id="reading" aria-pressed="false">Đọc liên tục</button><a class="action" href="Huong-dan-hang-hoan-V2.pdf" download>PDF</a><a class="action" href="Huong-dan-hang-hoan-V2.pptx" download>PowerPoint</a><a class="action poster-link" href="quy-trinh-nhan-hoan.html">Ảnh quy trình</a></div></nav><div class="stage"><main class="deck">'+''.join(parts)+'</main></div><nav class="bar-bottom" aria-label="Chuyển trang"><button id="prev">← Trước</button><span id="counter" aria-live="polite"></span><button id="next">Tiếp →</button></nav><script>'+script+'</script></body></html>'
(OUT/'index.html').write_text(html)
(ROOT/'docs/returns-v2/training/slide-content.json').write_text(json.dumps([{k:v for k,v in s.items() if k!='cls'} for s in slides],ensure_ascii=False,indent=2)+'\n')
print('Built',len(slides),'slides')
